<script setup>
import { useBackupContext } from '../../composables/useBackupContext.js';
const { jobs, selectedJobId, jobProgress, selectJob, cancelJob, retryJob } = useBackupContext();
const terminalStates = ['SUCCEEDED','FAILED','CANCELLED','CANCELED'];
const jobState = (job) => job.state || job.status || '';
</script>
<template><el-table :data="jobs" class="data-table" highlight-current-row><el-table-column label="任务编号" min-width="180"><template #default="{ row }"><span class="mono">#{{ row.id }}</span></template></el-table-column><el-table-column label="状态" width="130"><template #default="{ row }"><status-badge :value="jobState(row)" /></template></el-table-column><el-table-column label="进度" width="190"><template #default="{ row }"><el-progress :percentage="jobProgress(row)" :stroke-width="7" :show-text="true" /></template></el-table-column><el-table-column label="订单 / 文件" width="150"><template #default="{ row }">{{ row.orderCompleted || 0 }} / {{ row.orderTotal || 0 }} · {{ row.fileCompleted || 0 }} / {{ row.fileTotal || 0 }}</template></el-table-column><el-table-column label="失败原因" min-width="220" show-overflow-tooltip><template #default="{ row }"><span class="error-text">{{ row.failureCode || '-' }} {{ row.failureEvidence || '' }}</span></template></el-table-column><el-table-column label="操作" width="190" fixed="right"><template #default="{ row }"><el-button size="small" @click="selectJob(row)">详情</el-button><el-button v-if="!terminalStates.includes(jobState(row))" size="small" type="warning" plain @click="cancelJob(row)">取消</el-button><el-button v-if="terminalStates.includes(jobState(row)) && jobState(row) !== 'SUCCEEDED'" size="small" type="primary" plain @click="retryJob(row)">重试</el-button></template></el-table-column><template #empty><el-empty description="暂无任务" /></template></el-table></template>
